<script setup lang="ts">
import {computed,ref} from 'vue';import {useRoute} from 'vue-router';import {useI18n} from 'vue-i18n';import {ArrowUpRight,X,ChevronLeft,ChevronRight} from 'lucide-vue-next';import {projects,imagePath} from '../data/projects';import ProjectImage from '../components/ProjectImage.vue';import ProjectCard from '../components/ProjectCard.vue'
const route=useRoute(),{t}=useI18n();const project=computed(()=>projects.find(p=>p.id===route.params.id));const index=ref<number|null>(null);const other=computed(()=>projects.filter(p=>p.id!==route.params.id));function step(d:number){if(project.value&&index.value!==null)index.value=(index.value+d+project.value.images.length)%project.value.images.length}
</script>
<template><div v-if="project"><section class="bg-ink text-white py-20 md:py-28"><div class="wrap"><p class="eyebrow !text-[#a2b9ff] mb-5">{{t('portfolio.'+project.category)}} / RYSEN PORTFOLIO</p><h1 class="text-5xl md:text-7xl font-extrabold tracking-[-.055em]">{{t('projects.'+project.id+'.title')}}</h1><p class="text-[#b4c2d9] mt-6 text-lg max-w-2xl">{{t('projects.'+project.id+'.summary')}}</p><a :href="project.url" target="_blank" rel="noopener noreferrer" class="btn btn-primary mt-9">{{t('portfolio.visit')}} <ArrowUpRight :size="18"/></a></div></section><section class="section"><div class="wrap"><ProjectImage :src="imagePath(project.id,project.images[0],String(route.params.lang))" :alt="project.id" wide/><div class="grid md:grid-cols-2 gap-12 mt-16"><div><p class="eyebrow mb-4">01 / {{t('portfolio.background')}}</p><h2 class="text-2xl font-extrabold">{{t('portfolio.background')}}</h2><p class="muted mt-5 leading-8">{{t('projects.'+project.id+'.background')}}</p></div><div><p class="eyebrow mb-4">02 / {{t('portfolio.solution')}}</p><h2 class="text-2xl font-extrabold">{{t('portfolio.solution')}}</h2><p class="muted mt-5 leading-8">{{t('projects.'+project.id+'.solution')}}</p><div class="flex gap-2 flex-wrap mt-6"><span v-for="tag in project.tags" :key="tag" class="bg-paper rounded-md text-sm px-3 py-2">{{tag}}</span></div></div></div><div class="mt-20"><p class="eyebrow mb-4">03 / GALLERY</p><h2 class="text-3xl font-extrabold mb-9">{{t('portfolio.gallery')}}</h2><div class="grid md:grid-cols-2 gap-5"><button v-for="(file,i) in project.images" :key="file" class="text-left card" :aria-label="`Open image ${i+1}`" @click="index=i"><ProjectImage :src="imagePath(project.id,file,String(route.params.lang))" :alt="file" wide/><div class="px-5 py-4 flex justify-between text-sm font-semibold"><span>{{file}}</span><span class="text-accent">↗</span></div></button></div></div></div></section><section class="section bg-paper"><div class="wrap"><h2 class="section-title mb-10">{{t('portfolio.next')}}</h2><div class="grid md:grid-cols-2 gap-6"><ProjectCard v-for="p in other" :key="p.id" :project="p"/></div></div></section><div v-if="index!==null" class="fixed inset-0 bg-[#060b18]/95 z-[100] flex items-center justify-center p-5" role="dialog" aria-modal="true" @click.self="index=null"><button class="absolute top-5 right-5 text-white p-3" aria-label="Close" @click="index=null"><X/></button><button class="absolute left-2 md:left-8 text-white p-2" aria-label="Previous" @click="step(-1)"><ChevronLeft :size="32"/></button><div class="w-full max-w-5xl mx-12"><ProjectImage :src="imagePath(project.id,project.images[index],String(route.params.lang))" :alt="project.images[index]" wide/><p class="text-white/70 text-center mt-4">{{index+1}} / {{project.images.length}} · {{project.images[index]}}</p></div><button class="absolute right-2 md:right-8 text-white p-2" aria-label="Next" @click="step(1)"><ChevronRight :size="32"/></button></div></div><section v-else class="section wrap"><h1>Project not found</h1><RouterLink to="/ko/portfolio/" class="text-accent">Portfolio →</RouterLink></section></template>
